import { useMemo, useState } from 'react';

function ExpensiveComponent({ number }) {
  const result = useMemo(() => slowFunction(number), [number]);
  return <div>{result}</div>;
}

function slowFunction(num) {
  for (let i = 0; i < 1e7; i++) {} // simulate delay
  return num * 2;
}
```

